def is_lucky_digit(digit):
    return digit == '4' or digit == '7'

def is_lucky_number(n):
    count = 0
    for digit in str(n):
        if is_lucky_digit(digit):
            count += 1

    return is_lucky_digit(str(count))

n = int(input())

if is_lucky_number(n):
    print("YES")
