def is_lucky_number(x):
    s = str(x)
    for ch in s:
        if ch != "4" and ch != "7":
            return False
    return True


def main():
    input_string = int_to_arr()
    count = 0

    for i in input_string:
        if i in [4, 7]:
            count += 1
    out("YES" if count > 0 and is_lucky_number(count) else "NO")


